// --- DUST SHOP (Recycleur) ---

(function applyBalanceDustShopCosts() {
    const dust = BALANCE && BALANCE.SHOP_COSTS && BALANCE.SHOP_COSTS.DUST;
    if (!dust || typeof DUST_SHOP_ITEMS === 'undefined') return;
    const dustItems = DUST_SHOP_ITEMS as Record<string, unknown>;
    const dustRates = dust as Record<string, number>;
    Object.keys(dustRates).forEach((k) => {
        if (dustItems[k]) (dustItems[k] as Record<string, unknown>).cost = dustRates[k];
    });
})();
